'use client';

import { useId, useState, type CSSProperties, type ReactNode } from 'react';
import './before-after-wipe.css';

export interface BeforeAfterWipeProps {
  before: ReactNode;
  after: ReactNode;
  beforeLabel?: string;
  afterLabel?: string;
  /** Starting position of the divider, 0–100. */
  defaultValue?: number;
  className?: string;
}

/**
 * Two stacked states with a divider between them. The divider is a native
 * range input stretched over the image, so dragging, touch, arrow keys,
 * Home and End all work without extra code.
 */
export function BeforeAfterWipe({
  before,
  after,
  beforeLabel = 'Before',
  afterLabel = 'After',
  defaultValue = 50,
  className = '',
}: BeforeAfterWipeProps) {
  const [value, setValue] = useState(defaultValue);
  const id = useId();
  return (
    <div
      className={`mg-wipe ${className}`}
      style={{ '--mg-split': `${value}%` } as CSSProperties}
    >
      <div className='mg-wipe__layer'>{before}</div>
      <div className='mg-wipe__layer mg-wipe__layer--after'>{after}</div>
      <span className='mg-wipe__tag mg-wipe__tag--before' aria-hidden='true'>
        {beforeLabel}
      </span>
      <span className='mg-wipe__tag mg-wipe__tag--after' aria-hidden='true'>
        {afterLabel}
      </span>
      <input
        id={id}
        type='range'
        min={0}
        max={100}
        step={1}
        value={value}
        className='mg-wipe__range'
        aria-label={`Compare ${beforeLabel.toLowerCase()} and ${afterLabel.toLowerCase()}`}
        aria-valuetext={`${100 - value}% ${afterLabel.toLowerCase()}, ${value}% ${beforeLabel.toLowerCase()}`}
        onChange={(event) => setValue(Number(event.target.value))}
      />
      <span className='mg-wipe__handle' aria-hidden='true' />
    </div>
  );
}

.mg-wipe {
  position: relative;
  display: grid;
  overflow: hidden;
  border-radius: 14px;
  user-select: none;
}

.mg-wipe__layer {
  grid-area: 1 / 1;
}

.mg-wipe__layer > * {
  display: block;
  width: 100%;
  height: auto;
}

/* The "after" state shows to the right of the divider. */
.mg-wipe__layer--after {
  clip-path: inset(0 0 0 var(--mg-split));
}

.mg-wipe__tag {
  position: absolute;
  top: 10px;
  padding: 2px 8px;
  border-radius: 6px;
  background: rgba(12, 23, 56, 0.78);
  color: #fff;
  font-size: 12px;
  font-weight: 600;
}

.mg-wipe__tag--before {
  left: 10px;
}

.mg-wipe__tag--after {
  right: 10px;
}

/* The real control covers the whole image but is invisible. */
.mg-wipe__range {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: ew-resize;
  appearance: none;
}

.mg-wipe__handle {
  position: absolute;
  top: 0;
  bottom: 0;
  left: var(--mg-split);
  width: 3px;
  margin-left: -1.5px;
  background: #fff;
  box-shadow: 0 0 0 1px rgba(12, 23, 56, 0.3);
  pointer-events: none;
}

.mg-wipe__handle::after {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 36px;
  height: 36px;
  border: 3px solid #fff;
  border-radius: 50%;
  background: var(--mg-accent, #164cff);
  content: '';
  transform: translate(-50%, -50%);
}

.mg-wipe__range:focus-visible + .mg-wipe__handle::after {
  outline: 3px solid var(--mg-green, #b6ff3b);
  outline-offset: 2px;
}
